const first = items?.[0]?.json ?? {};

const baseCandidates = [
  first.body,
  first.data,
  first.response,
  first.html,
  first.content,
  JSON.stringify(first)
].filter((v) => typeof v === 'string' && v.length > 0);

const extractEnterpriseUrls = (text) => {
  const urls = new Set();
  const directRegex = /https:\/\/www\.melnick\.com\.br\/enterprise\/[A-Za-z0-9\-_/]+/gi;
  while (true) {
    const match = directRegex.exec(text);
    if (!match) break;
    const clean = match[0].replace(/["'<>]/g, '').replace(/\/$/, '') + '/';
    urls.add(clean);
  }
  return urls;
};

const allUrls = new Set();
let pagesConsultadas = 1;

for (const u of extractEnterpriseUrls(baseCandidates.join('\n\n'))) {
  allUrls.add(u);
}

// Pagina automaticamente pelo mesmo endpoint usado pelo botao "Ver mais".
// Para quando nao houver novos links por 2 paginas seguidas.
let emptyStreak = 0;
const maxPages = 30;

for (let page = 2; page <= maxPages; page++) {
  let responseText = '';
  try {
    const form = new URLSearchParams({
      action: 'enterprises_ajax',
      search_type: '',
      search_mode: 'more',
      search_page: String(page),
      search_order: '',
      search_term: '',
      search_filters: ''
    });

    const resp = await fetch('https://www.melnick.com.br/wp-admin/admin-ajax.php', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8'
      },
      body: form.toString()
    });

    responseText = await resp.text();
    pagesConsultadas = page;
  } catch (e) {
    break;
  }

  if (!responseText || responseText.length < 40) {
    emptyStreak += 1;
    if (emptyStreak >= 2) break;
    continue;
  }

  const before = allUrls.size;
  for (const u of extractEnterpriseUrls(responseText)) {
    allUrls.add(u);
  }
  const after = allUrls.size;

  if (after === before) {
    emptyStreak += 1;
  } else {
    emptyStreak = 0;
  }

  if (emptyStreak >= 2) break;
}

const links = [...allUrls].sort();

if (!links.length) {
  return [
    {
      json: {
        etapa: 1,
        status: 'sem_links_encontrados',
        observacao: 'Nao foi possivel localizar URLs /enterprise/ no retorno bruto nem na paginacao.',
        baseUrl: 'https://www.melnick.com.br/empreendimentos/',
        pagesConsultadas,
        debug: {
          chavesDisponiveis: Object.keys(first),
          tamanhoCandidates: baseCandidates.map((c) => c.length)
        }
      }
    }
  ];
}

return links.map((url, index) => ({
  json: {
    etapa: 1,
    indice: index + 1,
    totalEncontrado: links.length,
    pagesConsultadas,
    empreendimentoUrl: url,
    origem: 'enterprise_html_mais_ajax'
  }
}));
